result = Customers.WHERE(
    COUNT(transactions_made) >= 5
).CALCULATE(
    customer_name=name,
    success_rate=100.0 * COUNT(transactions_made.WHERE(LOWER(status) == LOWER('success'))) / COUNT(transactions_made)
).ORDER_BY(success_rate.ASC())

result = Broker.CALCULATE(
    num_customers = COUNT(
        Customers.WHERE(
            ENDSWITH(email, '.com') & 
            HAS(
                transactions_made.WHERE(
                    CONTAINS(ticker.symbol, 'AMZN') |
                    CONTAINS(ticker.symbol, 'AAPL') |
                    CONTAINS(ticker.symbol, 'GOOGL') |
                    CONTAINS(ticker.symbol, 'META') |
                    CONTAINS(ticker.symbol, 'NFLX')
                )
            ) == 1
        )
    )
)

result = Customers.WHERE(
    (join_date >= "2023-01-01") & 
    (LOWER(status) == "active")
).PARTITION(
    name="countries", 
    by=country
).CALCULATE(
    country=country,
    count=COUNT(Customers)
)

tac_by_country = Customers.WHERE(
    (LOWER(status) == 'active') & (join_date >= '2023-01-01')
).PARTITION(
    name='country_groups', by=(country)
).CALCULATE(
    country=country,
    tac_count=COUNT(Customers)
)

result = Drugs.CALCULATE(
    drug_name=drug_name,
    avg_ddd=AVG(
        treatments_used_in.WHERE(
            PRESENT(end_dt)
        ).CALCULATE(
            ddd=tot_drug_amt / DATEDIFF("days", start_dt, end_dt)
        ).ddd
    )
)

avg_ddd_per_drug = Drugs.CALCULATE(
    drug_name=drug_name,
    average_ddd=AVG(
        treatments_used_in.WHERE(
            (PRESENT(end_dt) == 1) & (DATEDIFF("days", start_dt, end_dt) > 0)
        ).CALCULATE(
            ddd_value=tot_drug_amt / DATEDIFF("days", start_dt, end_dt)
        ).ddd_value
    )
)

result = DermTreatment.CALCULATE(
    num_patients_gmail_yahoo = COUNT(
        Patients.WHERE(
            ENDSWITH(LOWER(email), "@gmail.com") | ENDSWITH(LOWER(email), "@yahoo.com")
        )
    )
)

gmail_or_yahoo_patients_count = DermTreatment.CALCULATE(
    num_patients=COUNT(
        Patients.WHERE(
            ENDSWITH(LOWER(email), '@gmail.com') | ENDSWITH(LOWER(email), '@yahoo.com')
        )
    )
)

result = DermTreatment.CALCULATE(
    patient_count=COUNT(
        Patients.WHERE(
            HAS(
                treatments_received.WHERE(
                    (LOWER(diagnosis.diag_name) == LOWER('Psoriasis vulgaris')) &
                    (LOWER(drug.drug_type) == LOWER('Biologic'))
                )
            ) == 1
        )
    )
)

psoriasis_biologic_patient_count = DermTreatment.CALCULATE(
    num_patients=NDISTINCT(
        Treatments.WHERE(
            (LOWER(diagnosis.diag_name) == 'psoriasis vulgaris') & 
            (LOWER(drug.drug_type) == 'biologic')
        ).patient.patient_id
    )
)

# Calculate the date range: from 6 months ago to the start of current month
result = DermTreatment.CALCULATE(
    num_treatments=COUNT(
        Patients.WHERE(
            LOWER(first_name) == LOWER('Alice')
        ).treatments_received.WHERE(
            (start_dt >= DATETIME('now', 'start of month', '-6 months')) &
            (start_dt < DATETIME('now', 'start of month'))
        )
    )
)

alice_recent_treatments = DermTreatment.CALCULATE(
    start_of_current_month=DATETIME('now', 'start of month'),
    start_of_period=DATETIME('now', 'start of month', '-6 months')
).CALCULATE(
    num_treatments=COUNT(
        Patients.WHERE(LOWER(first_name) == 'alice').treatments_received.WHERE(
            (start_dt >= start_of_period) & (start_dt < start_of_current_month)
        )
    )
)

result = Patients.WHERE(
    (LOWER(gender) == 'male') & 
    (LOWER(ins_type) == 'private')
).CALCULATE(
    age_in_years = DATEDIFF("years", date_of_birth, DATETIME('now'))
).CALCULATE(
    average_age = AVG(age_in_years)
)

avg_age_of_patients = DermTreatment.CALCULATE(
    avg_patient_age=AVG(
        Patients.WHERE(
            (LOWER(gender) == 'male') & (LOWER(ins_type) == 'private')
        ).CALCULATE(
            age_in_years=DATEDIFF("years", date_of_birth, DATETIME('now'))
        ).age_in_years
    )
)

weekly_notification_summary = Ewallet.CALCULATE(
    start_date_limit=DATETIME('now', 'start of week', '-3 weeks'),
    end_date_limit=DATETIME('now', 'start of week')
).Users.WHERE(
    ISIN(country, ('US', 'Canada'))
).notifications.WHERE(
    (created_at >= start_date_limit) & (created_at < end_date_limit)
).CALCULATE(
    notification_week=DATETIME(created_at, 'start of week'),
    is_weekend=ISIN(DAYNAME(created_at), ('Saturday', 'Sunday'))
).PARTITION(
    name='weekly_notifications', by=(notification_week)
).CALCULATE(
    week=notification_week,
    total_notifications=COUNT(Notifications),
    weekend_notifications=SUM(Notifications.is_weekend)
).ORDER_BY(week.ASC())

result = Users.WHERE(LOWER(country) == LOWER('US')).transactions_sent.WHERE(
    DATEDIFF("days", created_at, DATETIME('now')) <= 7
).CALCULATE(
    num_transactions=COUNT(Transactions),
    total_amount=SUM(amount)
).SINGULAR()
